<script setup lang="ts">
import type {Definition,Answer} from '@survey/shared';
import {evaluateAnswers,QUESTION_LABELS} from '@survey/shared';
const props=defineProps<{definition:Definition;answers?:Answer[]}>();
function value(id:string){const a=props.answers?.find(a=>a.questionId===id),q=props.definition.questions.find(q=>q.id===id)!;if(!a)return props.answers?(evaluateAnswers(props.definition.questions,props.answers).path.some(q=>q.id===id)?'未回答':'已跳过'):'';if(a.type==='number')return a.number;if(a.type==='text')return a.text;const ids=a.type==='single'?[a.optionId]:a.optionIds;return ids.map(id=>q.options?.find(o=>o.id===id)?.label??'未知选项').join('、');}
function ruleText(q:Definition['questions'][number],rule:Definition['questions'][number]['jumpRules'][number]){const condition=rule.condition,operators:Record<string,string>={eq:'等于',lt:'小于',lte:'小于等于',gt:'大于',gte:'大于等于',containsAny:'包含任意',containsAll:'包含全部'};const ids=condition.optionIds??(condition.optionId?[condition.optionId]:[]);const value=condition.number??ids.map(id=>q.options?.find(o=>o.id===id)?.label??'失效选项').join('、');return `${operators[condition.op]} ${value}`;}
</script>
<template><div class="readonly-definition"><p class="description">{{definition.description}}</p><section v-for="(q,index) in definition.questions" :key="q.id" class="panel"><h3>{{index+1}}. {{q.title}}</h3><small>{{QUESTION_LABELS[q.type]}} · {{q.required?'必答':'可选'}}</small><template v-if="answers"><p class="answer-value">{{value(q.id)}}</p></template><template v-else><ul v-if="q.options"><li v-for="option in q.options" :key="option.id">{{option.label}}</li></ul><p v-if="q.validation" class="muted">{{q.type==='number'?`数字范围：${q.validation.min??'不限'} 至 ${q.validation.max??'不限'}；${q.validation.integerOnly?'整数':'允许小数'}`:q.type==='text'?`文本长度：${q.validation.minLength??0} 至 ${q.validation.maxLength??10000}`:q.type==='multiple'?`选择数量：${q.validation.minChoices??(q.required?1:0)} 至 ${q.validation.maxChoices??q.options?.length}`:''}}</p><p v-for="(rule,n) in q.jumpRules" :key="rule.id" class="muted">规则 {{n+1}}：{{ruleText(q,rule)}} → 第 {{definition.questions.findIndex(q=>q.id===rule.targetQuestionId)+1}} 题</p></template></section></div></template>
